def gilliland_stages(n_min: float, r_min: float, r_actual: float) -> float:
    """Molokanov et al. (1972) analytical fit to the Gilliland correlation:
    X = (R-Rmin)/(R+1), Y = 1 - exp[(1+54.4X)/(11+117.2X) * (X-1)/sqrt(X)],
    Y = (N-Nmin)/(N+1) solved for N."""
    if r_actual <= r_min:
        raise ValueError("actual reflux ratio must exceed the minimum reflux ratio")
    X = (r_actual - r_min) / (r_actual + 1)
    if X <= 0:
        return n_min
    Y = 1 - math.exp(((1 + 54.4 * X) / (11 + 117.2 * X)) * ((X - 1) / math.sqrt(X)))
    return (n_min + Y) / (1 - Y)

def calculate_efficiency(self) -> float:
    """Calculate PEM efficiency"""
    if self.current_power == 0:
        return 0.0

    # Efficiency based on load (typically 60-75%)
    load_factor = self.current_power / self.specs.nominal_power
    efficiency = self.specs.min_efficiency + (self.specs.max_efficiency - self.specs.min_efficiency) * load_factor
    return min(efficiency, self.specs.max_efficiency)

def reduction_pct(lcef_value: float, baseline: float = CORSIA_BASELINE_GCO2_PER_MJ) -> float:
    if baseline <= 0:
        return 0.0
    return round((1 - lcef_value / baseline) * 100, 2)


def is_corsia_eligible(ghg_reduction_pct: float) -> bool:
    return ghg_reduction_pct >= CORSIA_MIN_REDUCTION_PCT


def tco2e_saved(volume_liters: float, lcef_value: float, baseline: float = CORSIA_BASELINE_GCO2_PER_MJ) -> float:
    """tCO2e emissions reduction credited for a given airline delivery, using the
    CORSIA baseline (89 gCO2e/MJ) -- not the RED III fossil comparator."""
    mj = volume_liters * SAF_ENERGY_DENSITY_MJ_PER_L
    saved_g = mj * (baseline - lcef_value)
    return round(saved_g / 1_000_000, 3)

