def fetch(page, retries=5):
    for a in range(retries):
        try:
            r = sess.get(BASE, params={"limit": LIMIT, "page": page}, timeout=40)
            if r.status_code == 200:
                return page, r.json().get("results", [])
            if r.status_code == 404:      # past the end
                return page, []
            time.sleep(2 * (a + 1))
        except Exception:
            time.sleep(2 * (a + 1))
    return page, None

